-- Migracao pontual: marca como encerrados os processos da BBS/Souza
-- Cruz que ja estao com situacao Encerrado na planilha de origem, mas
-- ainda constavam como ativo (ou outro status) no FaroLex. So mexe em
-- status -- nao altera fase, valor, observacao nem qualquer outro campo.

begin;

create temporary table planilha_bbs_encerrados (cnj text primary key) on commit drop;


update public.processos p
set status = 'encerrado'
from planilha_bbs_encerrados pl
where regexp_replace(p.numero_cnj, E'\\D', '', 'g') = pl.cnj
  and p.status <> 'encerrado';

select count(*) as atualizados from planilha_bbs_encerrados;

commit;
